// You write:
suspend fun loadProfile(id: String): Profile {
    val user = api.getUser(id)        // suspension point 1
    val prefs = api.getPrefs(id)      // suspension point 2  (sequential!)
    return Profile(user, prefs)
}

// Conceptually becomes a state machine:
//   label 0 -> call api.getUser, save `id`, return COROUTINE_SUSPENDED
//   label 1 -> receive user, save it, call api.getPrefs, return COROUTINE_SUSPENDED
//   label 2 -> receive prefs, build Profile, resume caller

// For real concurrency you must opt in:
suspend fun loadProfileFast(id: String): Profile = coroutineScope {
    val user = async { api.getUser(id) }
    val prefs = async { api.getPrefs(id) }
    Profile(user.await(), prefs.await())
}

// All-or-nothing: if either call fails, the whole screen load fails.
suspend fun loadScreen(): Screen = coroutineScope {
    val header = async { api.header() }
    val body   = async { api.body() }
    Screen(header.await(), body.await())
}

// Independent: a failing analytics ping must not kill the prefetch.
suspend fun warmUp() = supervisorScope {
    launch { runCatching { analytics.ping() } }
    launch { runCatching { imagePrefetcher.warm() } }
}

// Cooperative cancellation in CPU-bound work
suspend fun hash(blocks: List<Block>) = withContext(Dispatchers.Default) {
    blocks.map { block ->
        ensureActive()          // without this, cancellation is ignored
        expensiveHash(block)
    }
}

class FeedViewModel(private val repo: FeedRepo) : ViewModel() {

    private val _state = MutableStateFlow<UiState>(UiState.Loading)
    val state: StateFlow<UiState> = _state.asStateFlow()

    fun refresh() {
        viewModelScope.launch {
            _state.value = UiState.Loading
            _state.value = try {
                UiState.Content(repo.load())
            } catch (e: CancellationException) {
                throw e                       // never swallow cancellation
            } catch (e: IOException) {
                UiState.Error(e, retryable = true)
            }
        }
    }
}

// Handler is only consulted at the ROOT of the scope:
val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main +
    CoroutineExceptionHandler { _, e -> logger.e("unhandled", e) })

class UserRepository(
    private val api: UserApi,
    private val dao: UserDao,
    private val io: CoroutineDispatcher = Dispatchers.IO   // injected for tests
) {
    // Main-safe: callers never need withContext
    suspend fun refresh(id: String): User = withContext(io) {
        val dto = api.fetch(id)          // Retrofit suspend — already main-safe
        dao.upsert(dto.toEntity())       // Room suspend — already main-safe
        dto.toDomain()
    }

    // CPU-bound work belongs on Default, not IO
    suspend fun rank(users: List<User>): List<User> =
        withContext(Dispatchers.Default) { users.sortedByDescending { it.score } }
}

class SearchViewModel(private val repo: Repo) : ViewModel() {

    private val query = MutableStateFlow("")

    // Shared, lifecycle-aware UI state
    val results: StateFlow<List<Item>> = query
        .debounce(300)
        .filter { it.length >= 2 }
        .flatMapLatest { repo.search(it) }        // cancels the previous search
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())

    // One-shot events: replay = 0 so rotation does not re-deliver
    private val _events = MutableSharedFlow<Event>(replay = 0, extraBufferCapacity = 1)
    val events: SharedFlow<Event> = _events.asSharedFlow()

    fun onQueryChange(q: String) { query.value = q }
}

val results: Flow<List<Item>> = queryFlow
    .debounce(300)                       // wait for typing to settle
    .map { it.trim() }
    .distinctUntilChanged()              // ignore no-op edits
    .filter { it.length >= 2 }
    .flatMapLatest { q ->                // cancel the stale request
        repo.search(q)
            .catch { emit(emptyList()) } // catch applies to UPSTREAM only
    }
    .flowOn(Dispatchers.IO)              // everything above runs on IO

